+void ScreenBrightnessController::adjustBrightnessStep(const QString &displayId,
+                                                      PowerDevil::BrightnessLogic::StepAdjustmentAction adjustment,
+                                                      const QString &sourceClientName,
+                                                      const QString &sourceClientContext,
+                                                      IndicatorHint hint)
+{
+    if (const auto it = m_displaysById.find(displayId); it != m_displaysById.end() && !it->second.zombie) {
+        const int newBrightness = it->second.brightnessLogic.adjusted(adjustment);
+        if (newBrightness >= 0) {
+            setBrightness(displayId, newBrightness, sourceClientName, sourceClientContext, hint);
+        }
+    } else {
+        qCWarning(POWERDEVIL) << "Adjust screen brightness step failed: no display with id" << displayId;
+    }
+}
