+
+void ScreenBrightnessAgent::actOnActiveDisplayBrightnessKey(BrightnessLogic::StepAdjustmentAction action)
+{
+    if (!m_controller->isSupported()) {
+        return;
+    }
+    QDBusMessage msg = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"activeOutputName"_s);
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(msg), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, action](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        const QDBusPendingReply<QString> reply = *watcher;
+        if (reply.isError()) {
+            qCWarning(POWERDEVIL) << "Could not get the active screen from KWin:" << reply.error().message();
+            return;
+        }
+        const QString displayId = reply.value();
+        if (!m_controller->displayIds().contains(displayId)) {
+            qCDebug(POWERDEVIL) << "Active screen" << displayId << "has no brightness control";
+            return;
+        }
+        m_controller->adjustBrightnessStep(displayId, action, u"(internal)"_s, u"brightness_key"_s, ScreenBrightnessController::ShowIndicator);
+    });
+}
 }

